CREATE POLICY "gallery_work_lock" ON "author_works" AS PERMISSIVE FOR UPDATE TO "sep_runtime" USING ("author_works"."organization_id" = nullif(current_setting('sep.organization_id', true), '')::uuid AND "author_works"."event_id"=nullif(current_setting('sep.event_id',true),'')::uuid AND current_setting('sep.gallery_staff',true)='true') WITH CHECK (false);--> statement-breakpoint
ALTER POLICY "gallery_public_read" ON "gallery_releases" TO sep_runtime USING ("gallery_releases"."organization_id" = nullif(current_setting('sep.organization_id', true), '')::uuid AND "gallery_releases"."event_id"=nullif(current_setting('sep.event_id',true),'')::uuid AND current_setting('sep.gallery_public',true)='true');